import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.C-si7TFR.js";const m=JSON.parse('{"title":"Installation and deployment","description":"","frontmatter":{"title":"Installation and deployment"},"headers":[],"relativePath":"guide/deployment.md","filePath":"guide/deployment.md"}'),r={name:"guide/deployment.md"};function i(s,e,l,d,c,p){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="installation-and-deployment" tabindex="-1">Installation and deployment <a class="header-anchor" href="#installation-and-deployment" aria-label="Permalink to &quot;Installation and deployment&quot;">​</a></h1><h2 id="choose-a-package" tabindex="-1">Choose a package <a class="header-anchor" href="#choose-a-package" aria-label="Permalink to &quot;Choose a package&quot;">​</a></h2><p>Select the operating system and architecture from the <a href="https://iolinker.com/#cta" target="_blank" rel="noreferrer">official download section</a>. The website&#39;s <code>version.json</code> is the only maintained source of versions and package addresses; documentation does not maintain a second download list.</p><p>Guides reflect current source and do not imply that every package in the version file contains all capabilities. External package availability requires separate pre-release verification.</p><h2 id="start-and-secure" tabindex="-1">Start and secure <a class="header-anchor" href="#start-and-secure" aria-label="Permalink to &quot;Start and secure&quot;">​</a></h2><ol><li>Extract and start the program in a controlled environment. Read its actual startup log and local address.</li><li>Use the installed version&#39;s actual port, data directory, HTTPS and listen-address configuration; do not copy parameters from an old tutorial.</li><li>Change the initial password immediately after the first login and complete account security.</li><li>Do not expose the service publicly or to untrusted networks before authentication, access control and backups are configured.</li></ol><p>Old startup articles are historical references. This guide supplies no fixed default password, and a running process is not automatically safe for public exposure.</p><h2 id="external-dependencies" tabindex="-1">External dependencies <a class="header-anchor" href="#external-dependencies" aria-label="Permalink to &quot;External dependencies&quot;">​</a></h2><p>A local deployment does not mean every dependency is local:</p><ul><li>Models, embeddings, search, MCP and other external services may need network access, credentials and separate accounts.</li><li>Prompts, retrieved snippets, tool parameters and business data may be sent to external services according to your configuration.</li><li>Verify Python, Lua and third-party command runtimes in the target environment. A script node does not imply that every runtime is installed.</li><li>Model or network failures can cause waiting tasks, failures or unavailable diagnosis.</li></ul><h2 id="tools-and-remote-access" tabindex="-1">Tools and remote access <a class="header-anchor" href="#tools-and-remote-access" aria-label="Permalink to &quot;Tools and remote access&quot;">​</a></h2><ul><li>Restrict file and command tools to an explicit working directory and use a least-privilege operating-system account.</li><li>Use controlled targets and parameter binding for external HTTP, database and SSH operations; never concatenate user input into commands or SQL.</li><li>Run only reviewed MCP STDIO programs. Prefer HTTPS for external services and restrict access to internal addresses through deployment policy.</li><li>Configure a user allowlist for WeCom remote control and rotate exposed Secrets at the provider.</li><li>Remove tokens, personal data and real business information before sharing configuration, screenshots, execution records or traces.</li></ul><h2 id="capability-boundaries" tabindex="-1">Capability boundaries <a class="header-anchor" href="#capability-boundaries" aria-label="Permalink to &quot;Capability boundaries&quot;">​</a></h2><p>No micro-system/general business-page builder, unlimited sub-agent nesting, one-click deployment across every channel, row/field-level authorization or unconditional performance metric is promised. Use the visible agent, workflow, data-table, form and tool capabilities according to their documented prerequisites.</p>',14)])])}const h=a(r,[["render",i]]);export{m as __pageData,h as default};
